typedef void (*step_fn)(long *n, long *r);
step_fn even(long *n, long *r), odd(long *n, long *r);   /* each returns the next step */

step_fn even(long *n, long *r) { if (*n == 0) { *r = 1; return NULL; } *n -= 1; return odd; }
step_fn odd(long *n, long *r)  { if (*n == 0) { *r = 0; return NULL; } *n -= 1; return even; }

long run(long n) {
    long r;
    step_fn f = even;
    while (f) f = f(&n, &r);   /* the driver never nests */
    return r;
}
